ps.pstext:
if !IsFeatureImplemented(FEAT_SME_F8F32) then EndOfDecode(Decode_UNDEF); end;
let v : integer = UInt('010'::Rv);
let n : integer = UInt(Zn::'0');
let m : integer = UInt('0'::Zm);
let offset : integer = UInt(off3);
let index : integer = UInt(i2h::i2l);
let esize : integer{} = 32;

CheckFPMREnabled();
CheckStreamingSVEAndZAEnabled();
let VL : integer{} = CurrentVL();
let elements : integer = VL DIV esize;
let vectors : integer = VL DIV 8;
let vstride : integer = vectors DIV 4;
let eltspersegment : integer = 128 DIV esize;
let vbase : bits(32) = X{32}(v);
var vec : integer = (UInt(vbase) + offset) MOD vstride;
var result : bits(VL);

for r = 0 to 3 do
    let operand1a : bits(VL) = Z{VL}(n+0);
    let operand1b : bits(VL) = Z{VL}(n+1);
    let operand2 : bits(VL) = Z{VL}(m);
    let operand3 : bits(VL) = ZAvector{VL}(vec);
    for e = 0 to elements-1 do
        var op1 : bits(16);
        op1[0+:8] = operand1a[(4 * e + r)*:8];
        op1[1*:8] = operand1b[(4 * e + r)*:8];
        let segmentbase : integer = e - e MOD eltspersegment;
        let s : integer = 2 * (segmentbase + index);
        let op2 : bits(16) = operand2[s*:16];
        var sum : bits(esize) = operand3[e*:esize];
        sum = FP8DotAddFP{32, 16}(sum, op1, op2, FPCR(), FPMR());
        result[e*:esize] = sum;
    end;

    ZAvector{VL}(vec) = result;
    vec = vec + vstride;
end;
